import {mkdtemp,writeFile,readFile,rm,mkdir,symlink} from 'node:fs/promises';
import {spawnSync} from 'node:child_process';
import path from 'node:path';
import os from 'node:os';
import assert from 'node:assert/strict';
const dir=await mkdtemp(path.join(os.tmpdir(),'legendgirl-baseline-'));
try {
 const archive=spawnSync('git',['-C','/Users/sergio/repos/legendGirl','archive','HEAD'],{maxBuffer:256*1024*1024});assert.equal(archive.status,0);
 const unpack=spawnSync('tar',['-x','-C',dir],{input:archive.stdout});assert.equal(unpack.status,0);
 await symlink(path.resolve('node_modules'),path.join(dir,'node_modules'));
 await mkdir(path.join(dir,'scripts'),{recursive:true});
 await writeFile(path.join(dir,'scripts/test-toy-room-sword-camera.js'),await readFile('scripts/test-toy-room-sword-camera.js'));
 const result=spawnSync('node',['scripts/test-toy-room-sword-camera.js'],{cwd:dir,encoding:'utf8'});
 assert.equal(result.status,1);assert.ok(result.stderr.includes('O contrato anterior de cameraTarget deve permanecer em COLLECTING.'));
 console.log('CONFIRMADO: a mesma expectativa de cameraTarget em COLLECTING falha no HEAD 44654efb, anterior às mudanças desta sessão.');
 console.log(result.stderr);
} finally {await rm(dir,{recursive:true,force:true});}
